module timer_32bit (  
    input wire clk,  
    input wire reset,  
    output reg [31:0] timer_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            timer_out <= 32'b0;  
        else  
            timer_out <= timer_out + 1;  
    end  
endmodule

