module PLL_8x (  
    input wire clk_ref,  
    input wire reset,  
    output reg clk_out  
);  
    reg [2:0] state;  
    reg [2:0] next_state;  
    reg [2:0] counter;  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            state <= 3'b000;  
            counter <= 3'b000;  
            clk_out <= 0;  
        end else begin  
            state <= next_state;  
            if (state == 3'b111) begin  
                clk_out <= ~clk_out;  
                counter <= 3'b000;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  

    always @(*) begin  
        case (state)  
            3'b000: next_state = 3'b001;  
            3'b001: next_state = 3'b010;  
            3'b010: next_state = 3'b011;  
            3'b011: next_state = 3'b100;  
            3'b100: next_state = 3'b101;  
            3'b101: next_state = 3'b110;  
            3'b110: next_state = 3'b111;  
            3'b111: next_state = 3'b000;  
            default: next_state = 3'b000;  
        endcase  
    end  
endmodule

