module pitch_detection (  
    input clk,  
    input reset,  
    input signed [15:0] audio_signal,  
    output reg [15:0] detected_pitch  
);  

    reg signed [15:0] max_signal;  
    reg [3:0] peak_counter;  
    reg [15:0] pitch_value;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            max_signal <= 0;  
            detected_pitch <= 0;  
            peak_counter <= 0;  
        end  
        else begin  
            if (audio_signal > max_signal) begin  
                max_signal <= audio_signal;  
            end  
            else begin  
                peak_counter <= peak_counter + 1;  
                if (peak_counter == 4'd10) begin  
                    detected_pitch <= max_signal;  
                    max_signal <= 0;  
                    peak_counter <= 0;  
                end  
            end  
        end  
    end  
endmodule

