module bst(clk, rst, insert_key, search_key, insert_enable, search_enable, found);  
  input clk;  
  input rst;  
  input [7:0] insert_key;  
  input [7:0] search_key;  
  input insert_enable;  
  input search_enable;  
  output reg found;  

  reg [7:0] key;  
  reg [7:0] left_key;  
  reg [7:0] right_key;  
  reg is_left_valid, is_right_valid;  

  always @(posedge clk or posedge rst) begin  
    if (rst) begin  
      key <= 8'b0;  
      left_key <= 8'b0;  
      right_key <= 8'b0;  
      is_left_valid <= 0;  
      is_right_valid <= 0;  
      found <= 0;  
    end else begin  
      if (insert_enable) begin  
        if (key == 8'b0) begin  
          key <= insert_key;  
        end else if (insert_key < key) begin  
          is_left_valid <= 1;  
          left_key <= insert_key;  
        end else if (insert_key > key) begin  
          is_right_valid <= 1;  
          right_key <= insert_key;  
        end  
      end  
      if (search_enable) begin  
        if (search_key == key) begin  
          found <= 1;  
        end else if (is_left_valid && search_key < key) begin  
          found <= (search_key == left_key);  
        end else if (is_right_valid && search_key > key) begin  
          found <= (search_key == right_key);  
        end else begin  
          found <= 0;  
        end  
      end  
    end  
  end  
endmodule

