module PISO_Shift_Register(  
    input wire clk,  
    input wire load,  
    input wire [7:0] parallel_in,  
    output reg serial_out  
);  
    reg [7:0] shift_reg;  
    integer count;  

    always @(posedge clk) begin  
        if (load) begin  
            shift_reg <= parallel_in;  
            count <= 7;  
        end else if (count >= 0) begin  
            serial_out <= shift_reg[count];  
            count <= count - 1;  
        end  
    end  
endmodule

