module adaptive_lms_filter (
    input clk,
    input reset,
    input signed [15:0] x,       // Reference input
    input signed [15:0] d,       // Desired output
    output signed [15:0] y,      // Filter output
    output signed [15:0] e       // Error signal
);
    parameter N = 4;             // Number of taps
    parameter mu = 16'h0001;     // Step size for adaptation

    reg signed [15:0] w [0:N-1]; // Weights
    reg signed [15:0] x_reg [0:N-1]; // Input samples
    reg signed [15:0] y_reg;      // Filter output
    reg signed [15:0] e_reg;      // Error signal

    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'h0000; // Initialize weights to zero
            end
            y_reg <= 16'h0000;
            e_reg <= 16'h0000;
        end else begin
            // Shift input samples
            for (i = N-1; i > 0; i = i - 1) begin
                x_reg[i] <= x_reg[i-1];
            end
            x_reg[0] <= x;

            // Calculate filter output
            y_reg = 16'h0000;
            for (i = 0; i < N; i = i + 1) begin
                y_reg = y_reg + (w[i] * x_reg[i]);
            end

            // Calculate error
            e_reg = d - y_reg;

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] = w[i] + (mu * e_reg * x_reg[i]);
            end
        end
    end

    assign y = y_reg;
    assign e = e_reg;

endmodule

