module fractional_n_pll(  
    input wire clk_ref,  
    input wire reset,  
    input wire [3:0] divide_ratio,  
    output reg clk_out  
);  

reg [3:0] counter;  

always @(posedge clk_ref or posedge reset) begin  
    if (reset) begin  
        counter <= 0;  
        clk_out <= 0;  
    end else begin  
        if (counter < divide_ratio) begin  
            clk_out <= ~clk_out;  
            counter <= counter + 1;  
        end else begin  
            counter <= 0;  
        end  
    end  
end  

endmodule

