module crc_generator(  
    input wire clk,  
    input wire reset,  
    input wire [15:0] data_in,  
    input wire start,  
    output reg [15:0] crc_out  
);  
    reg [15:0] crc_reg;  
    reg [4:0] bit_count;  
    parameter POLYNOMIAL = 16'hA001; // x^16 + x^12 + x^5 + 1  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            crc_reg <= 16'hFFFF;  
            crc_out <= 16'h0000;  
            bit_count <= 0;  
        end else if (start) begin  
            if (bit_count < 16) begin  
                crc_reg <= {crc_reg[14:0], 1'b0} ^ (crc_reg[15] ? POLYNOMIAL : 16'h0000);  
                bit_count <= bit_count + 1;  
            end else begin  
                crc_out <= ~crc_reg;  
            end  
        end  
    end  
endmodule

