module phase_shifter(
    input clk,
    input [4:0] phase_control,
    input [4:0] delay_control,
    output reg [4:0] phase_shifted_output
);
    reg [4:0] phase_buffer [0:31];
    integer i;

    always @(posedge clk) begin
        // Shift the phase buffer
        for (i = 0; i < 31; i = i + 1) begin
            phase_buffer[i] <= phase_buffer[i + 1];
        end
        phase_buffer[31] <= phase_control;

        // Output the delayed phase
        phase_shifted_output <= phase_buffer[delay_control];
    end
endmodule

