module vco (
    input wire clk,
    input wire [2:0] control_voltage, // 3-bit input to represent 0V to 5V
    output reg freq_out
);
    reg [31:0] counter = 0;
    reg [31:0] frequency = 0;

    always @(posedge clk) begin
        // Map control_voltage to frequency
        case (control_voltage)
            3'b000: frequency <= 32'd1000000; // 1MHz
            3'b001: frequency <= 32'd2000000; // 2MHz
            3'b010: frequency <= 32'd4000000; // 4MHz
            3'b011: frequency <= 32'd6000000; // 6MHz
            3'b100: frequency <= 32'd8000000; // 8MHz
            3'b101: frequency <= 32'd10000000; // 10MHz
            default: frequency <= 32'd1000000; // default to 1MHz
        endcase

        // Generate frequency output
        counter <= counter + 1;
        if(counter >= (50000000 / frequency)) begin // Assuming 50MHz clock
            freq_out <= ~freq_out; // Toggle output
            counter <= 0;
        end
    end
endmodule

