module serializer (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire start,
    output reg serial_out,
    output reg valid
);
    reg [3:0] bit_count; // to keep track of the number of bits serialized
    reg [7:0] shift_reg; // to hold the data being serialized

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 0;
            serial_out <= 0;
            valid <= 0;
            shift_reg <= 0;
        end else if (start) begin
            shift_reg <= data_in; // load data into shift register
            bit_count <= 0;
            valid <= 0;
        end else if (bit_count < 8) begin
            serial_out <= shift_reg[bit_count]; // send out LSB first
            bit_count <= bit_count + 1;
            valid <= 1; // output is valid for each bit
        end else begin
            valid <= 0; // no more valid output after 8 bits
        end
    end
endmodule

