module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire [7:0] data_in,
    input wire send,
    output reg tx,
    output reg busy
);
    reg [3:0] bit_count;
    reg [9:0] shift_reg;
    reg state; // 0 = idle, 1 = transmitting

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // idle state
            busy <= 0;
            bit_count <= 0;
            state <= 0;
        end else if (send && !busy) begin
            busy <= 1;
            state <= 1;
            shift_reg <= {1'b1, data_in, 1'b0}; // stop bit, data, start bit
            bit_count <= 0;
        end else if (state) begin
            if (bit_count < 10) begin
                tx <= shift_reg[bit_count];
                bit_count <= bit_count + 1;
            end else begin
                tx <= 1; // idle state
                busy <= 0;
                state <= 0;
            end
        end
    end
endmodule

