module deserializer (
    input wire clk,
    input wire reset,
    input wire [31:0] data_in,
    output reg [7:0] data_out,
    output reg valid
);
    reg [2:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 3'b000;
            data_out <= 8'b00000000;
            valid <= 1'b0;
        end
        else begin
            data_out <= data_in[count * 8 +: 8];
            valid <= 1'b1;
            count <= count + 1;
            if (count == 3'b111) begin
                valid <= 1'b0; // Set valid low after last output
                count <= 3'b000; // Reset count
            end
        end
    end
endmodule

