module serializer (
    input clk,
    input rst,
    input start,
    input [15:0] parallel_data,
    output reg serial_out,
    output reg done
);
    reg [3:0] bit_counter;
    reg [15:0] data_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            bit_counter <= 0;
            serial_out <= 0;
            done <= 0;
        end else if (start) begin
            data_reg <= parallel_data;
            bit_counter <= 0;
            done <= 0;
        end else if (bit_counter < 16) begin
            serial_out <= data_reg[15 - bit_counter]; // Send MSB first
            bit_counter <= bit_counter + 1;
            if (bit_counter == 15) begin
                done <= 1;
            end
        end
    end
endmodule

